@startuml

class OOBank {}

class OrganizationalUnit {}

class Division extends OrganizationalUnit {}

class Subdivision extends OrganizationalUnit {}

class Branch extends Subdivision {
  +address : string
  +branchNumber : int
}

class Employee {}

class Manager {}

class Customer {}

class Account {
  +accountNumber : string
  +balance : double
  +creditOrOverdraftLimit : double
}

class AccountType {
  +interestRate : float
  +monthlyFee : float
  +privileges : string[]
}

class MortgageAccount extends Account {}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  +expiryDate : date
}

class Property {}

class SecondaryCard {}

OOBank "1" -- "*" Division
Division "1" -- "*" Subdivision
Subdivision "1" -- "*" Branch
Division "1" -- "0..1" Manager
Division "1" -- "*" Employee
Branch "1" -- "*" Account
Branch "1" -- "*" Customer
Customer "1..2" -- "*" Account
Account "*" -- "1" AccountType
MortgageAccount "1" -- "1" Property : collateral
CreditCardAccount "1" -- "*" SecondaryCard

@enduml

